
import './PlantillaPages.css'
import logoleyseca from '../../assets/leysecalogo2.png'
import BotonPerfil from '../BotonPerfil/BotonPerfil';
import { XyzTransition } from "@animxyz/react";
import { useFuncionesPerfil } from '../../hooks/useFuncionesPerfil';
import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import BotonNotificaciones from '../BotonNotificaciones/BotonNotificaciones';


export default function PlantillaPages({ header, navigation, main, footer, sucursal,id_sucursal, nombreUsuario, apellidoUsuario, esSuperAdmin, rol, configuraciones,token }) {

  /////////// NAVEGACION A PERFIL O CONFIGURACIONES y CERRAR SESION
  const [opcionesPerfil, setOpcionesPerfil] = useState(false);

  //////////FUNCION PRIMMERA LETRA DE UNA PALABRA EN MAYUSCULAS
  const transformaMayusucula = (str) => {
    return str.replace(/\b\w/g, (char) => char.toUpperCase());
  };

  //para panel de principal
  const clickPerfil = () => {
    setOpcionesPerfil(!opcionesPerfil);
  }

  //para panel de configuaaciones
  const navegarHacia = useNavigate();
  const clickVender = () => {
    navegarHacia('/vender');
  }


  const { irAPerfil, irAConfiguraciones, cerrarSesion } = useFuncionesPerfil(); //HOOK PARA NAVEGAR Y CERRAR SESION


  return (
    <div className="__plantilla_paginas">
      {/* TOP BAR CON LOGO Y DATOS DEL USUARIO */}
      <div className="__topbar">
        <div className="__topbar_logo_seccion">
          <img src={logoleyseca} alt="Ley Seca" className="__topbar_logo" />
          <span className="__topbar_nombre_empresa">LEY SECA</span>
        </div>

        <div className="__topbar_usuario_seccion">
           {!configuraciones && (
            <BotonNotificaciones
              id_sucursal={id_sucursal} 
              token={token}
            />
          )}
          <span className="__topbar_usuario_info">
            {`Usuario: ${transformaMayusucula(nombreUsuario)} ${transformaMayusucula(apellidoUsuario)} `} <strong>Rol: {`${transformaMayusucula(rol)}`}</strong>
            {esSuperAdmin ? `` : `Sucursal: ${sucursal}`}
          </span>


          {configuraciones ? (<div className='__boton_perfil __boton_home_imagen'>
            <BotonPerfil onClick={clickVender} title="Ir a vender" ></BotonPerfil>
          </div>) : (<div className= {esSuperAdmin ? '__boton_perfil __boton_perfil_imagen_superadmin' : 
            (rol === 'admin' ? '__boton_perfil __boton_perfil_imagen' : '__boton_perfil __boton_perfil_imagen' )
            }>
            <BotonPerfil onClick={clickPerfil} title="Ir al Perfil" />

            <XyzTransition
              xyz="fade small-100% duration-3 origin-top"
              appear
            >
              {opcionesPerfil && (
                <ul className="__sugerencias">
                  <li onClick={irAPerfil}>Datos</li>
                  <li onClick={irAConfiguraciones}>Configuraciones</li>
                  <li onClick={cerrarSesion}>Cerrar Sesión</li>
                </ul>
              )}
            </XyzTransition>

          </div>)}
        </div>
      </div>
      <header>{header}</header> {/* Panel de filtros */}
      <nav>{navigation}</nav>  {/* Pestañas de botones */}
      <main >{main}</main>    {/* Tabla con datos */}
      <footer>{footer}</footer>  {/* Botones de interacción con la tabla */}
    </div>
  );
};