import './BotonNotificaciones.css';
import { useState, useEffect, useRef } from 'react';
import { XyzTransition } from "@animxyz/react";

export default function BotonNotificaciones({ id_sucursal, token }) {
  const [alertas, setAlertas] = useState([]);
  const [abierto, setAbierto] = useState(false);
  const [cargando, setCargando] = useState(false);
  const intervaloRef = useRef(null);

  // Obtener alertas al montar el componente
  useEffect(() => {
    if (id_sucursal && token) {
      obtenerAlertas();
    }

    return () => {
      if (intervaloRef.current) {
        clearInterval(intervaloRef.current);
      }
    };
  }, [id_sucursal, token]);

  // Función para traer alertas
  const obtenerAlertas = async () => {
    setCargando(true);
    try {
  const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/alerta-stock`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          id_sucursal: id_sucursal
        })
      });

      if (!respuesta.ok) {
        console.error('Error al obtener alertas');
        return;
      }

      const datos = await respuesta.json();
      setAlertas(datos);
    } catch (error) {
      console.error('Error en la solicitud:', error);
    } finally {
      setCargando(false);
    }
  };

  // Función para manejar el click del botón
  const handleClickBoton = () => {
    const nuevoAbierto = !abierto;
    setAbierto(nuevoAbierto);

    // Si se abre, obtener alertas y empezar el intervalo de 60 segundos
    if (nuevoAbierto) {
      obtenerAlertas();

      // Si ya hay un intervalo, lo limpiamos
      if (intervaloRef.current) {
        clearInterval(intervaloRef.current);
      }

      // Configurar intervalo de 60 segundos solo cuando está abierto
      intervaloRef.current = setInterval(() => {
        obtenerAlertas();
      }, 60000); // 60 segundos
    } else {
      // Si se cierra, limpiar el intervalo
      if (intervaloRef.current) {
        clearInterval(intervaloRef.current);
        intervaloRef.current = null;
      }
    }
  };

  return (
    <div className="__boton_notificaciones_container">
      <button
        className={alertas.length > 0 ? "__boton_notificaciones __boton_notificaciones_imagen" : "__boton_notificaciones __boton_sin_notificaciones_imagen"}
        onClick={handleClickBoton}
        title="Alertas de Stock"
      >
        {/* Círculo con cantidad de alertas */}
        {alertas.length > 0 && (
          <div className="__badge_alertas">
            <span>{alertas.length}</span>
          </div>
        )}
      </button>

      <XyzTransition
        xyz="fade small-100% duration-3 origin-top"
        appear
      >
        {abierto && (
          <div className="__notificaciones_dropdown">
            <div className="__notificaciones_header">
              <h3>Alertas de Stock</h3>
              <span className="__notificaciones_cantidad">
                {alertas.length} Alerta{alertas.length !== 1 ? 's' : ''}
              </span>
            </div>

            {cargando && (
              <div className="__notificaciones_cargando">
                Cargando...
              </div>
            )}

            {!cargando && alertas.length === 0 && (
              <div className="__notificaciones_vacio">
                Sin alertas de stock
              </div>
            )}

            {!cargando && alertas.length > 0 && (
              <ul className="__notificaciones_lista">
                {alertas.map((alerta) => (
                  <li key={alerta.id_alerta} className="__notificacion_item">
                    <div className="__notificacion_producto">
                      <span className="__notificacion_nombre">
                        {alerta.producto}
                      </span>
                      <span className="__notificacion_stock">
                        Stock: <strong>{alerta.stock_actual}</strong>
                        <span className="__notificacion_minima">
                          (Mín: {alerta.alerta_minima})
                        </span>
                      </span>
                    </div>
                  </li>
                ))}
              </ul>
            )}

           
          </div>
        )}
      </XyzTransition>

      {/* Fondo oscuro para cerrar al hacer click afuera */}
      {abierto && (
        <div
          className="__notificaciones_backdrop"
          onClick={() => setAbierto(false)}
        />
      )}
    </div>
  );
}